//! The page's view of the core is generated from the core itself, so the two cannot drift apart:
//!
//! - `core/pkg/snaptiles_core.d.ts`: the module type, one method per `extern "C" fn core_*` in `src/ffi.rs`;
//! - `src/sim/core-layout.ts`: the state buffer's slot indices and strides (`src/state.rs` `layout!` lists), the
//!   layout version, the text separator, the key count and `ApiName`, the script API's function names (`api()`).
//!
//! The test also checks that `.cargo/config.toml` exports exactly those functions. It fails when a generated file is
//! out of date; `UPDATE_BINDINGS=1 cargo test --release --test bindings` rewrites them.
use snaptiles_core::ffi::TEXT_SEP;
use snaptiles_core::sim::keys::KEY_COUNT;
use snaptiles_core::state::*;
use std::fs;
use std::path::PathBuf;

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

/// (name, [(param, type)], return type) of every `extern "C" fn core_*`, in source order
fn ffi_functions() -> Vec<(String, Vec<(String, String)>, Option<String>)> {
    let src = fs::read_to_string(root().join("src/ffi.rs")).unwrap();
    let mut out = Vec::new();
    for (start, _) in src.match_indices("extern \"C\" fn core_") {
        let rest = &src[start + "extern \"C\" fn ".len()..];
        let name = &rest[..rest.find('(').unwrap()];
        let params = &rest[rest.find('(').unwrap() + 1..rest.find(')').unwrap()];
        let after = &rest[rest.find(')').unwrap() + 1..rest.find('{').unwrap()];
        let params = params
            .split(',')
            .map(str::trim)
            .filter(|p| !p.is_empty())
            .map(|p| {
                let (n, t) = p.split_once(':').unwrap();
                (n.trim().to_string(), t.trim().to_string())
            })
            .collect();
        let ret = after.trim().strip_prefix("->").map(|t| t.trim().to_string());
        out.push((name.to_string(), params, ret));
    }
    out
}

/// every C type the ABI uses is a number in JavaScript (pointers are byte offsets into the module's memory)
fn ts_type(rust: &str) -> &'static str {
    match rust {
        "u32" | "i32" | "usize" | "f64" | "*const u8" | "*const f64" => "number",
        other => panic!("ffi type {other} has no JavaScript mapping here: add it to tests/bindings.rs"),
    }
}

fn camel(snake: &str) -> String {
    let mut s = String::new();
    let mut up = false;
    for c in snake.chars() {
        if c == '_' {
            up = true;
        } else if up {
            s.extend(c.to_uppercase());
            up = false;
        } else {
            s.push(c);
        }
    }
    s
}

fn dts() -> String {
    let mut s = String::from(
        "// GENERATED by core/tests/bindings.rs from core/src/ffi.rs: do not edit. Rewrite with\n\
         // `UPDATE_BINDINGS=1 cargo test --release --test bindings` (in core/).\n\
         export interface SnapTilesCoreModule {\n  HEAPU8: Uint8Array;\n  HEAPF64: Float64Array;\n  UTF8ToString(ptr: number): string;\n  _malloc(n: number): number;\n  _free(ptr: number): void;\n",
    );
    for (name, params, ret) in ffi_functions() {
        let ps: Vec<String> = params.iter().map(|(n, t)| format!("{}: {}", camel(n), ts_type(t))).collect();
        let r = ret.as_deref().map(ts_type).unwrap_or("void");
        s += &format!("  _{name}({}): {r};\n", ps.join(", "));
    }
    s += "}\ndeclare const SnapTilesCore: (options?: Record<string, unknown>) => Promise<SnapTilesCoreModule>;\nexport default SnapTilesCore;\n";
    s
}

fn record(name: &str, fields: &[&str], length_name: &str) -> String {
    let body: Vec<String> = fields.iter().enumerate().map(|(i, f)| format!("  {f}: {i},")).collect();
    format!("export const {name} = {{\n{}\n}} as const;\nexport const {length_name} = {};\n", body.join("\n"), fields.len())
}

fn layout_ts() -> String {
    let mut s = String::from(
        "// GENERATED by core/tests/bindings.rs from core/src/state.rs, ffi.rs, sim/keys.rs and sim/api.rs: do not edit.\n\
         // Rewrite with `UPDATE_BINDINGS=1 cargo test --release --test bindings` (in core/). The state buffer layout is\n\
         // documented in core/src/state.rs; slot indices are relative to the start of the header or of each record.\n",
    );
    s += &format!("export const LAYOUT_VERSION = {LAYOUT_VERSION};\n");
    s += &format!("/** separator of the multi-row strings (`core_out`, `core_val_names`) */\nexport const TEXT_SEP = '\\u{:04x}';\n", TEXT_SEP.chars().next().unwrap() as u32);
    s += &format!("export const KEY_COUNT = {KEY_COUNT};\n");
    s += &record("HEADER", HEADER_FIELDS, "HEADER_LENGTH");
    s += &record("TILE", TILE_FIELDS, "TILE_STRIDE");
    s += &record("BALL", BALL_FIELDS, "BALL_STRIDE");
    s += &record("CRATE", CRATE_FIELDS, "CRATE_STRIDE");
    s += &record("SHELL", SHELL_FIELDS, "SHELL_STRIDE");
    let mut names: Vec<&str> = snaptiles_core::sim::api().iter().map(|(n, _)| *n).collect();
    names.sort();
    names.dedup();
    s += "/** the script API's functions (`api()` of the simulation), as the core's table names them */\nexport type ApiName =\n";
    s += &names.iter().map(|n| format!("  | '{n}'")).collect::<Vec<_>>().join("\n");
    s += ";\n";
    s
}

fn check(path: PathBuf, want: String, failures: &mut Vec<String>) {
    let have = fs::read_to_string(&path).unwrap_or_default().replace("\r\n", "\n");
    if have == want {
        return;
    }
    if std::env::var("UPDATE_BINDINGS").is_ok() {
        fs::write(&path, want).unwrap();
    } else {
        failures.push(path.display().to_string());
    }
}

#[test]
fn generated_page_bindings_are_current() {
    let mut failures = Vec::new();
    check(root().join("pkg/snaptiles_core.d.ts"), dts(), &mut failures);
    check(root().join("../src/sim/core-layout.ts"), layout_ts(), &mut failures);
    assert!(failures.is_empty(), "out of date: {failures:?}; run `UPDATE_BINDINGS=1 cargo test --release --test bindings` in core/ and commit them");
}

#[test]
fn the_emscripten_build_exports_exactly_the_ffi_functions() {
    let config = fs::read_to_string(root().join(".cargo/config.toml")).unwrap();
    let list = config.split("-sEXPORTED_FUNCTIONS=").nth(1).expect("EXPORTED_FUNCTIONS in .cargo/config.toml");
    let list = &list[..list.find(|c: char| c == '"' || c.is_whitespace()).unwrap_or(list.len())];
    let mut exported: Vec<&str> = list.split(',').collect();
    exported.sort();
    let mut want: Vec<String> = vec!["_malloc".into(), "_free".into()];
    want.extend(ffi_functions().into_iter().map(|(n, _, _)| format!("_{n}")));
    want.sort();
    assert_eq!(exported, want);
}
